#!/usr/bin/env python3
"""Generate the original LamOS ASCII bitmap font (5x7 ink in an 8x16 cell)."""
import pathlib
# Each digit is one five-bit row. These original shapes also define punctuation.
upper=['0e11111f111111','1e11111e11111e','0e11101010110e','1e11111111111e','1f10101e10101f','1f10101e101010','0e11101711110f','1111111f111111','0e04040404040e','0702020212120c','11121418141211','1010101010101f','111b1515111111','11191513111111','0e11111111110e','1e11111e101010','0e11111115120d','1e11111e141211','0f10100e01011e','1f040404040404','1111111111110e','11111111110a04','1111111515150a','11110a040a1111','11110a04040404','1f01020408101f']
lower=['00000e010f110f','10101e1111111e','00000f1010100f','01010f1111110f','00000e111f100f','0608081e080808','00000f110f010e','10101e11111111','04000c0404040e','0200060202120c','101011121c1211','0c04040404040e','00001a15151515','00001e11111111','00000e1111110e','00001e111e1010','00000f110f0101','00001619101010','00000f100e011e','08081e08080906','0000111111130d','00001111110a04','0000111515150a','0000110a040a11','000011110f010e','00001f0204081f']
digits=['0e11131519110e','040c040404040e','0e11010204081f','1e01010e01011e','02060a121f0202','1f10101e01011e','0e10101e11110e','1f010204080808','0e11110e11110e','0e11110f01010e']
punct={' ':'00000000000000','!':'04040404040004','"':'0a0a0a00000000','#':'0a1f0a0a1f0a00','$':'040f140e051e04','%':'19190204081313','&':'0c12140c15120d',"'":'04040800000000','(':'02040808080402',')':'08040202020408','*':'00150e1f0e1500','+':'0004041f040400',',':'00000000000408','-':'0000001f000000','.':'00000000000004','/':'01020204080810',':':'00000400000400',';':'00000400000408','<':'01020408040201','=':'00001f001f0000','>':'10080402040810','?':'0e110102040004','@':'0e11171517100f','[':'0e08080808080e','\\':'10080804020201',']':'0e02020202020e','^':'040a1100000000','_':'0000000000001f','`':'08040200000000','{':'06080810080806','|':'04040404040404','}':'0c02020102020c','~':'00000a15000000'}
glyphs={**punct,**dict(zip('ABCDEFGHIJKLMNOPQRSTUVWXYZ',upper)),**dict(zip('abcdefghijklmnopqrstuvwxyz',lower)),**dict(zip('0123456789',digits))}
assert len(glyphs)==95
out=['/* SPDX-License-Identifier: GPL-3.0-only */','/* Generated by tools/fontgen.py; original LamOS bitmap shapes. */','static const uint8_t ascii_8x16[95][16] = {']
for code in range(32,127):
    rows=[int(glyphs[chr(code)][i:i+2],16)<<1 for i in range(0,14,2)]
    bitmap=[0]+[v for row in rows for v in (row,row)]+[0]
    out.append('    {'+', '.join(f'0x{v:02x}' for v in bitmap)+'}, /* '+str(code)+' */')
out.append('};')
(pathlib.Path(__file__).resolve().parents[1]/'lib/font_data.inc').write_text('\n'.join(out)+'\n')
